/// <summary>
/// Data contract for the <c>AAXFreeTextInvoicePostedBusinessEvent</c> business event.
/// </summary>
[DataContract]
public final class AAXFreeTextInvoicePostedBusinessEventContract extends BusinessEventsContract
{
    private DataAreaId legalEntity;
    private InvoiceId invoiceId;
    private CustAccount customerAccount;
    private InvoiceDate invoiceDate;
    private AmountMST invoiceAmount;
    private CurrencyCode currencyCode;

}

