/// <summary>
/// Creates a new <c>AAXFreeTextInvoicePostedBusinessEventContract</c> from the specified <c>CustInvoiceJour</c> record.
/// </summary>
/// <param name="_custInvoiceJour">The source CustInvoiceJour record.</param>
/// <returns>A new populated instance of <c>AAXFreeTextInvoicePostedBusinessEventContract</c>.</returns>
public static AAXFreeTextInvoicePostedBusinessEventContract newFromCustInvoiceJour(CustInvoiceJour _custInvoiceJour)
{
    var contract = new AAXFreeTextInvoicePostedBusinessEventContract();
    contract.initialize(_custInvoiceJour);

    return contract;
}

/// <summary>
/// Initializes the contract fields from the source record.
/// </summary>
/// <param name="_custInvoiceJour">The source CustInvoiceJour record.</param>
private void initialize(CustInvoiceJour _custInvoiceJour)
{
    legalEntity = _custInvoiceJour.DataAreaId;
    invoiceId = _custInvoiceJour.InvoiceId;
    customerAccount = _custInvoiceJour.InvoiceAccount;
    invoiceDate = _custInvoiceJour.InvoiceDate;
    invoiceAmount = _custInvoiceJour.InvoiceAmountMST;
    currencyCode = _custInvoiceJour.CurrencyCode;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Gets or sets the legal entity.
/// </summary>
/// <param name="_legalEntity">The legal entity value.</param>
/// <returns>The legal entity value.</returns>
[DataMember('legalEntity'), BusinessEventsDataMember("Legal Entity")]
public DataAreaId parmLegalEntity(DataAreaId _legalEntity = legalEntity)
{
    legalEntity = _legalEntity;

    return legalEntity;
}

/// <summary>
